# coding: utf-8
"""
Script to generate a Python class with all wrapped calls from OpenAPI client APIs.
"""
import sys
import importlib
import inspect
import os


API_PACKAGE = "plantscreen.api"
OUTPUT_FILE = "plantscreen/complete_api_client.py"

# Requires plantscreen to be installed with pip!
#  pip install .
# Only wraps around the functions themselves. 
# Not the  *_with_http_info and *_without_preload_content which are also generated by the OpenAPI generator, but are not commonly used. 
# If needed, this can be added in a future iteration.


def add_to_init():
    # --- Add CompleteAPIClient to __init__.py ---
    init_path = os.path.join(os.path.dirname(OUTPUT_FILE), "__init__.py")
    with open(init_path, "r", encoding="utf-8") as f:
        init_lines = f.readlines()
    # Add import if not present
    import_line = "from plantscreen.complete_api_client import CompleteAPIClient\n"
    if not any("CompleteAPIClient" in l and "import" in l for l in init_lines):
        # Find first non-comment, non-docstring line after imports
        insert_at = 0
        for i, l in enumerate(init_lines):
            if l.strip().startswith("from") or l.strip().startswith("import"):
                insert_at = i + 1
        init_lines.insert(insert_at, import_line)
    # Add to __all__ if not present
    for i, l in enumerate(init_lines):
        if l.strip().startswith("__all__"):
            # Find the closing bracket
            for j in range(i, len(init_lines)):
                if "]" in init_lines[j]:
                    if '"CompleteAPIClient"' not in ''.join(init_lines[i:j+1]):
                        # Insert before closing bracket
                        init_lines.insert(j, '    "CompleteAPIClient",\n')
                    break
            break
    with open(init_path, "w", encoding="utf-8") as f:
        f.writelines(init_lines)
    print(f"Generated API client written to {OUTPUT_FILE} and added to __init__.py")


def get_json_field_from_return_type(api_module, return_type):
    # Helper to get the json_* field from the return type
    if return_type is inspect._empty:
        return None, False
    # If it's a string annotation, resolve it
    if isinstance(return_type, str):
        try:
            return_type = eval(return_type, api_module.__dict__)
        except Exception:
            return None, False
    # Prefer model_fields (Pydantic v2+), fallback to __fields__ (v1)
    if hasattr(return_type, 'model_fields'):
        fields = getattr(return_type, 'model_fields')
        if isinstance(fields, dict) and fields:
            return list(fields.keys())[0], False
    elif hasattr(return_type, '__fields__'):
        fields = getattr(return_type, '__fields__')
        if isinstance(fields, dict) and fields:
            return list(fields.keys())[0], False
    # Try __annotations__
    if hasattr(return_type, '__annotations__'):
        ann = return_type.__annotations__
        if ann:
            return list(ann.keys())[0], False
    return None, False


def generate_combined_api_client():
    # --- Generate the combined API client class ---

    # Dynamically import the API package
    api_module = importlib.import_module(API_PACKAGE)

    # Find all API classes
    api_classes = [getattr(api_module, name) for name in dir(api_module) if name.endswith('Api') and name[0].isupper()]

    class_lines = [
        "# coding: utf-8",
        '"""',
        'Auto-generated API client wrapper with direct methods for all endpoints.',
        '"""',
        'from plantscreen.api_client import ApiClient',
        'import plantscreen.api as api_module',
        '',
        '',
        'class CompleteAPIClient(ApiClient):',
        '    def __init__(self, *args, **kwargs):',
        '        super().__init__(*args, **kwargs)',
    ]
    for api_cls in api_classes:
        class_lines.append(f'        self._{api_cls.__name__} = api_module.{api_cls.__name__}(self)')
    class_lines.append('')

    # For each API class, add its public methods to the wrapper
    for api_cls in api_classes:
        for name, method in inspect.getmembers(api_cls, predicate=inspect.isfunction):
            if (
                name.startswith('_') or name == '__init__' or
                name.endswith('_with_http_info') or name.endswith('_without_preload_content')
            ):
                continue
            sig = inspect.signature(method)
            params = [p for p in sig.parameters.values() if p.name != 'self']
            param_defs = []
            call_args = []
            for p in params:
                if p.default is not inspect._empty:
                    param_defs.append(f"{p.name}={repr(p.default)}")
                else:
                    param_defs.append(p.name)
                call_args.append(p.name)
            params_str = ', '.join(param_defs)
            call_args_str = ', '.join(call_args)
            # Dynamically determine the correct json_* attribute
            return_type = sig.return_annotation
            json_field, is_api_response = get_json_field_from_return_type(sys.modules[api_cls.__module__], return_type)
            if is_api_response:
                if params_str:
                    class_lines.append(f'    def {name}(self, {params_str}):')
                    class_lines.append(f'        result = self._{api_cls.__name__}.{name}({call_args_str})')
                    class_lines.append(f'        return getattr(result, "data", None)')
                else:
                    class_lines.append(f'    def {name}(self):')
                    class_lines.append(f'        result = self._{api_cls.__name__}.{name}()')
                    class_lines.append(f'        return getattr(result, "data", None)')
            elif json_field:
                # Special handling for synthetic oneOf response models (e.g., Probe200Response)
                if return_type.__name__.endswith("200Response") and hasattr(return_type, "__annotations__") and "type" in return_type.__annotations__:
                    if params_str:
                        class_lines.append(f'    def {name}(self, {params_str}):')
                        class_lines.append(f'        result = self._{api_cls.__name__}.{name}({call_args_str})')
                        class_lines.append(f'        # Unwrap oneOf synthetic response using discriminator')
                        class_lines.append(f'        if hasattr(result, "type") and hasattr(result, "__dict__") and result.type:')
                        class_lines.append(f'            # Return the correct model instance based on discriminator')
                        class_lines.append(f'            return result')
                        class_lines.append(f'        return result')
                    else:
                        class_lines.append(f'    def {name}(self):')
                        class_lines.append(f'        result = self._{api_cls.__name__}.{name}()')
                        class_lines.append(f'        # Unwrap oneOf synthetic response using discriminator')
                        class_lines.append(f'        if hasattr(result, "type") and hasattr(result, "__dict__") and result.type:')
                        class_lines.append(f'            # Return the correct model instance based on discriminator')
                        class_lines.append(f'            return result')
                        class_lines.append(f'        return result')
                else:
                    if params_str:
                        class_lines.append(f'    def {name}(self, {params_str}):')
                        class_lines.append(f'        result = self._{api_cls.__name__}.{name}({call_args_str})')
                        class_lines.append(f'        return getattr(result, "{json_field}", None)')
                    else:
                        class_lines.append(f'    def {name}(self):')
                        class_lines.append(f'        result = self._{api_cls.__name__}.{name}()')
                        class_lines.append(f'        return getattr(result, "{json_field}", None)')
            else:
                if params_str:
                    class_lines.append(f'    def {name}(self, {params_str}):')
                    class_lines.append(f'        return self._{api_cls.__name__}.{name}({call_args_str})')
                else:
                    class_lines.append(f'    def {name}(self):')
                    class_lines.append(f'        return self._{api_cls.__name__}.{name}()')
            class_lines.append('')

    # Write to output file
    os.makedirs(os.path.dirname(OUTPUT_FILE), exist_ok=True)
    with open(OUTPUT_FILE, 'w', encoding='utf-8') as f:
        f.write('\n'.join(class_lines))


generate_combined_api_client()
add_to_init()
